      "content": "{\n  \"name\": \"@linxin666/dsh-client-ui-plugin-manager\",\n  \"description\": \"Update checking for the dsh web GUI's official Plugins page: compares installed plugins against the version their registry source serves, gates the update on the DSH runtime minimum the release declares, and drives the update through the official installer channel or this package's loopback CLI gateway.\",\n  \"version\": \"0.4.13\",\n  \"icon\": \"icon.svg\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./locale/en.json\": \"./locale/en.json\",\n    \"./locale/zh.json\": \"./locale/zh.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"engines\": {\n      \"dsh\": \">=0.2.1-rc.3\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-renderer\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsc -b tsconfig.build.json && tsdown\",\n    \"prepare\": \"tsdown\",\n    \"watch\": \"tsdown --watch\",\n    \"test\": \"vitest run\",\n    \"typecheck\": \"tsgo --noEmit\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \">=0.2.1-rc.3\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-api-workspace-controller\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-connection\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \"^0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.1-rc.3\",\n    \"@testing-library/react\": \"^16.1.0\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.5\",\n    \"@types/semver\": \"^7.8.0\",\n    \"jsdom\": \"^26.0.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"0.22.2\",\n    \"typescript\": \"~5.7.2\",\n    \"vitest\": \"^4.1.1\"\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"lib/**/*.js.map\",\n    \"lib/**/*.d.ts\",\n    \"lib/**/*.d.ts.map\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"README.i18n.yaml\",\n    \"icon.svg\",\n    \"locale\"\n  ],\n  \"license\": \"BSD-3-Clause\",\n  \"dependencies\": {\n    \"semver\": \"^7.8.5\",\n    \"yaml\": \"^2.8.2\"\n  }\n}\n"
